import itertools

def solve_small(n):
    black_squares = []
    white_squares = []
    for r in range(n):
        for c in range(n):
            if (r + c) % 2 == 0:
                black_squares.append((r, c))
            else:
                white_squares.append((r, c))

    B = len(black_squares)
    W = len(white_squares)

    # Generate all possible L-trominoes
    trominoes = []
    for r in range(n - 1):
        for c in range(n - 1):
            # The 4 possible L-trominoes in a 2x2 square
            # 1. Corner (r,c), others (r+1,c), (r,c+1)
            trominoes.append({(r, c), (r+1, c), (r, c+1)})
            # 2. Corner (r+1,c), others (r,c), (r+1,c+1)
            trominoes.append({(r+1, c), (r, c), (r+1, c+1)})
            # 3. Corner (r,c+1), others (r,c), (r+1,c+1)
            trominoes.append({(r, c+1), (r, c), (r+1, c+1)})
            # 4. Corner (r+1,c+1), others (r+1,c), (r,c+1)
            trominoes.append({(r+1, c+1), (r+1, c), (r, c+1)})

    # We want to cover all black squares using minimum number of non-overlapping trominoes.
    # This is a set cover-like problem.
    # Let's try to find the minimum N.
    for N in range(1, n*n):
        import itertools
        # This is too slow for large N. Let's use backtracking.
        def can_cover(covered_black, used_squares, tromino_idx, count):
            if len(covered_black) == B:
                return True
            if count == N:
                return False

            # Find the first uncovered black square
            target = None
            for b in black_squares:
                if b not in covered_black:
                    target = b
                    break

            # Try all trominoes that cover this target
            for t in trominoes:
                if target in t:
                    if t.isdisjoint(used_squares):
                        new_covered_black = covered_black | {s for s in t if s in black_squares}
                        if can_cover(new_covered_black, used_squares | t, 0, count + 1):
                            return True
            return False

        if can_cover(set(), set(), 0, 0):
            return N
    return None

