import z3

def solve_z3(n, N):
    B_squares = []
    W_squares = []
    for r in range(n):
        for c in range(n):
            if (r + c) % 2 == 0:
                B_squares.append((r, c))
            else:
                W_squares.append((r, c))

    B = len(B_squares)

    trominoes = []
    for r in range(n - 1):
        for c in range(n - 1):
            trominoes.append({(r, c), (r+1, c), (r, c+1)})
            trominoes.append({(r+1, c), (r, c), (r+1, c+1)})
            trominoes.append({(r, c+1), (r, c), (r+1, c+1)})
            trominoes.append({(r+1, c+1), (r+1, c), (r, c+1)})

    s = z3.Solver()
    # x_i is a boolean variable: is tromino i used?
    x = [z3.Bool(f'x_{i}') for i in range(len(trominoes))]

    # 1. Non-overlapping: each square covered by at most one tromino
    for r in range(n):
        for c in range(n):
            covered_by = [x[i] for i in range(len(trominoes)) if (r, c) in trominoes[i]]
            s.add(z3.AtMost(*covered_by, 1))

    # 2. All black squares covered: each black square covered by exactly one tromino
    for b in B_squares:
        covered_by = [x[i] for i in range(len(trominoes)) if b in trominoes[i]]
        s.add(z3.AtLeast(*covered_by, 1))

    # 3. Total number of trominoes is N
    s.add(z3.PbEq([x[i] for i in range(len(trominoes))], N, 1))

    if s.check() == z3.sat:
        return True
    else:
        return False

